// Scratch probe: does countVisibleCells agree with the real writer about how
// many cells a string occupies? Delete after use.
func TestScratchDriftVisibleCellsVsLength(t *testing.T) {
	cases := []struct {
		name string
		text string
	}{
		{"invisible then link end", "<transparent,transparent>abc</LINK>def"},
		{"invisible then style end", "<transparent,transparent>abc</>def"},
		{"plain", "abcdef"},
		{"invisible span", "<transparent,transparent>abc</>def"},
		{"link end while invisible", "<transparent,transparent>xx</LINK>yyyy"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			Init(shell.GENERIC)
			CurrentColors = &color.Set{Foreground: "#ffffff", Background: "#000000"}

			counted := VisibleCells(tc.text)

			Write("#000000", "#ffffff", tc.text)
			_, actual := String()

			assert.Equal(t, actual, counted, "VisibleCells=%d but rendered length=%d for %q", counted, actual, tc.text)
		})
	}
}

