import struct
import sys


def read_font(path):
    data = open(path, "rb").read()
    num_tables = struct.unpack(">H", data[4:6])[0]
    tables = {}
    for i in range(num_tables):
        off = 12 + i * 16
        tag = data[off:off + 4].decode("latin-1")
        toff, tlen = struct.unpack(">II", data[off + 8:off + 16])
        tables[tag] = (toff, tlen)
    return data, tables


def font_names(data, tables):
    if "name" not in tables:
        return []
    off, _ = tables["name"]
    count, string_off = struct.unpack(">HH", data[off + 2:off + 6])
    names = []
    for i in range(count):
        rec = off + 6 + i * 12
        pid, eid, lid, nid, ln, no = struct.unpack(">HHHHHH", data[rec:rec + 12])
        if nid not in (1, 4, 6):
            continue
        s = data[off + string_off + no:off + string_off + no + ln]
        try:
            text = s.decode("utf-16-be") if pid == 3 else s.decode("latin-1")
        except Exception:
            continue
        names.append((nid, text))
    return names


def cmap_codepoints(data, tables):
    if "cmap" not in tables:
        return set()
    off, _ = tables["cmap"]
    n = struct.unpack(">H", data[off + 2:off + 4])[0]
    best = None
    for i in range(n):
        rec = off + 4 + i * 8
        pid, eid, sub = struct.unpack(">HHI", data[rec:rec + 8])
        if (pid, eid) in ((3, 10), (3, 1), (0, 4), (0, 3)):
            best = off + sub
