                break
    if best is None:
        return set()
    fmt = struct.unpack(">H", data[best:best + 2])[0]
    cps = set()
    if fmt == 4:
        segx2 = struct.unpack(">H", data[best + 6:best + 8])[0]
        seg = segx2 // 2
        ends = [struct.unpack(">H", data[best + 14 + i * 2:best + 16 + i * 2])[0] for i in range(seg)]
        sbase = best + 16 + segx2
        starts = [struct.unpack(">H", data[sbase + i * 2:sbase + 2 + i * 2])[0] for i in range(seg)]
        for s, e in zip(starts, ends):
            if s == 0xFFFF:
                continue
            cps.update(range(s, min(e, 0xFFFF) + 1))
    elif fmt == 12:
        ngroups = struct.unpack(">I", data[best + 12:best + 16])[0]
        for i in range(ngroups):
            g = best + 16 + i * 12
            sc, ec, _ = struct.unpack(">III", data[g:g + 12])
            if ec - sc > 0x20000:
                continue
            cps.update(range(sc, ec + 1))
    return cps


