func (ir *Renderer) Init(env runtime.Environment) error {
	ir.setOutputPath(env.Flags().ConfigPath)

	ir.cleanContent()

	if err := ir.loadFonts(); err != nil {
		return err
	}

	ir.initDefaults()

	return nil
}

