	if !ir.Fonts.IsValid() {
		return ir.loadDefaultFonts()
	}

	fonts, err := ir.Fonts.Load()
	if err != nil {
		return err
	}

	ir.regular = fonts[regular]
	ir.bold = fonts[bold]
	ir.italic = fonts[italic]

	return nil
}

