217	function readPngDimensions(pngPath) {
218	  const buf = fs.readFileSync(pngPath);
219	  // IHDR is the first chunk in a well-formed PNG: 8-byte signature, 4-byte
220	  // length, 4-byte "IHDR", then width/height as big-endian uint32s.
221	  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
