224	// Renders svgMarkup inside a headless page whose viewport (at
225	// DEVICE_SCALE_FACTOR) targets targetWidth x targetHeight device pixels —
226	// the reference PNG's own dimensions — so the SVG's vector content is
227	// rescaled by the browser itself (crisp) rather than by resampling a raster
228	// afterwards. The SVG keeps its own viewBox, so content scales
229	// proportionally to fill the forced box.
230	async function rasterizeSVG(browser, svgMarkup, fontBase64, targetWidth, targetHeight) {
231	  const cssWidth = Math.max(1, Math.round(targetWidth / DEVICE_SCALE_FACTOR));
232	  const cssHeight = Math.max(1, Math.round(targetHeight / DEVICE_SCALE_FACTOR));
