234	  // The exporter's <svg> carries no preserveAspectRatio, so it defaults to
235	  // "xMidYMid meet": the browser would scale the viewBox uniformly to fit
236	  // inside the CSS box forced below and letterbox/center it, rather than
237	  // filling that box — which silently reintroduces a spatial offset between
238	  // the two rasters (content shifted down/right by the letterboxing gap)
239	  // that swamped the diff with edge noise before this fix. "none" makes the
240	  // two axes scale independently, actually filling cssWidth x cssHeight.
241	  svgMarkup = svgMarkup.replace("<svg ", '<svg preserveAspectRatio="none" ');
242	
243	  const context = await browser.newContext({
244	    viewport: { width: cssWidth, height: cssHeight },
245	    deviceScaleFactor: DEVICE_SCALE_FACTOR,
246	  });
247	
248	  const page = await context.newPage();
249	
250	  const html = `<!doctype html>
251	<html>
252	<head>
253	<meta charset="utf-8">
254	<style>
255	  @font-face {
256	    font-family: "${FONT_FAMILY}";
257	    src: url(data:font/ttf;base64,${fontBase64}) format("truetype");
258	    font-weight: normal;
259	    font-style: normal;
260	  }
261	  html, body { margin: 0; padding: 0; background: transparent; }
262	  /* Force the SVG's rendered box to exactly the viewport (which
263	     DEVICE_SCALE_FACTOR then rasterizes to targetWidth x targetHeight); the
264	     viewBox the exporter already wrote keeps the content proportional. */
265	  svg { display: block; width: 100vw; height: 100vh; }
266	</style>
267	</head>
268	<body>${svgMarkup}</body>
269	</html>`;
270	
271	  await page.setContent(html, { waitUntil: "networkidle" });
272	  await page.evaluate(() => document.fonts.ready);
273	  // One extra frame so the webfont swap (FOUT) has actually repainted
274	  // before the screenshot — document.fonts.ready resolves once the font is
275	  // *loaded*, not once the page has repainted with it.
276	  await page.waitForTimeout(50);
277	
278	  // omitBackground: true keeps the page's transparent regions transparent
279	  // in the captured PNG (alpha 0) instead of flattening them onto opaque
280	  // white. The reference PNG's own canvas outside the window+shadow is
281	  // genuinely transparent (image.go's gg context starts fully transparent
282	  // and is never filled) — matching that, rather than defaulting to white,
283	  // is what makes the outer margin diff meaningfully instead of reporting
284	  // "100% different" on every pixel of it.
285	  const buf = await page.screenshot({ omitBackground: true });
286	  await context.close();
287	
288	  return buf;
289	}
