394	    theme,
395	    pngDims: `${png.width}x${png.height}`,
396	    rasterDims: `${raster.width}x${raster.height}`,
397	    dimensionsMatched,
398	    structuralPct: (structuralDiffPixels / totalPixels) * 100,
399	    rawPct: (rawDiffPixels / totalPixels) * 100,
400	    files: {
401	      png: `${theme}.png`,
402	      raster: `${theme}.raster.png`,
403	      diff: `${theme}.diff.png`,
