func (e *Engine) markCursorAnchor() {
	if !terminal.CaptureRuns || len(e.capturedRows) == 0 {
		return
	}

	e.cursorRow = len(e.capturedRows) - 1
	e.cursorRun = len(e.capturedRows[e.cursorRow])
